svg.script:
(() => {
  const svg = document.documentElement;
  const overlay = svg.querySelector('#facility-overlay');
  const facilities = [...svg.querySelectorAll('.facility')];
  let pinned = null;
  svg.setAttribute('data-facility-interactive', 'true');
  function show(item) {
    overlay.replaceChildren();
    if (item) overlay.append(item.querySelector('.facility-tooltip').cloneNode(true));
  }
  function toggle(item) {
    pinned = pinned === item ? null : item;
    facilities.forEach(f => f.setAttribute('aria-pressed', String(f === pinned)));
    show(pinned);
  }
  function nearest(event) {
    const point = new DOMPoint(event.clientX, event.clientY).matrixTransform(svg.getScreenCTM().inverse());
    let winner = null, distance = 9;
    for (const item of facilities) {
      const d = Math.hypot(Number(item.dataset.x) - point.x, Number(item.dataset.y) - point.y);
      if (d < distance) { winner = item; distance = d; }
    }
    return winner;
  }
  svg.addEventListener('pointermove', event => show(nearest(event) || pinned));
  svg.addEventListener('pointerleave', () => show(pinned));
  facilities.forEach(item => {
    item.addEventListener('focus', () => show(item));
    item.addEventListener('blur', () => show(pinned));
    item.addEventListener('keydown', event => {
      if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); toggle(item); }
    });
  });
  const clear = () => { pinned = null; facilities.forEach(f => f.setAttribute('aria-pressed', 'false')); show(null); };
  svg.addEventListener('click', event => { const item = nearest(event); if (item) { item.focus(); toggle(item); } else clear(); });
  svg.addEventListener('keydown', event => { if (event.key === 'Escape') clear(); });
})();
